#!/usr/bin/env python3
from __future__ import annotations
import re, shutil, subprocess
from datetime import datetime
from pathlib import Path

CSS_CONTENT = "/* Royal Jeans — Elfo Denim Intro V9 (original assets, rebuilt motion) */\nhtml.elfo-intro-active,\nhtml.elfo-intro-active body { overflow: hidden !important; }\n\n#elfoIntroV3 {\n  position: fixed;\n  inset: 0;\n  z-index: 2147483000;\n  overflow: hidden;\n  direction: ltr;\n  user-select: none;\n  touch-action: none;\n  isolation: isolate;\n  --zip-y: 0px;\n  --zip-gap: 0px;\n  background: #06101a;\n}\n#elfoIntroV3[hidden] { display: none !important; }\n\n.elfo-v3-reveal {\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n  pointer-events: none;\n  background:\n    radial-gradient(ellipse at 50% 26%, rgba(255,214,150,.18), transparent 24%),\n    linear-gradient(180deg, #07121d 0%, #091727 48%, #06101a 100%);\n}\n\n.elfo-v3-panel {\n  position: absolute;\n  inset: -2px;\n  z-index: 5;\n  background-image: url('/static/denim-zip-v3.png?v=3');\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: cover;\n  filter: saturate(1.03) contrast(1.035) brightness(.96);\n  will-change: clip-path, transform, filter;\n  transition:\n    transform 1100ms cubic-bezier(.72,.01,.18,1),\n    filter 600ms ease;\n}\n.elfo-v3-panel::after {\n  content: '';\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  background:\n    radial-gradient(ellipse at 50% 4%, rgba(255,255,255,.09), transparent 32%),\n    radial-gradient(ellipse at 50% 108%, rgba(0,0,0,.22), transparent 50%),\n    linear-gradient(115deg, transparent 25%, rgba(255,255,255,.018) 43%, transparent 61%);\n  mix-blend-mode: screen;\n}\n\n.elfo-v3-left  { clip-path: polygon(0 0, 50% 0, 50% 100%, 0 100%); }\n.elfo-v3-right { clip-path: polygon(50% 0, 100% 0, 100% 100%, 50% 100%); }\n\n#elfoIntroV3.is-opening .elfo-v3-left {\n  transform: translate3d(-104%, 0, 0) rotate(-.42deg);\n  filter: brightness(.78) saturate(.98);\n}\n#elfoIntroV3.is-opening .elfo-v3-right {\n  transform: translate3d(104%, 0, 0) rotate(.42deg);\n  filter: brightness(.78) saturate(.98);\n}\n\n.elfo-v3-open-light {\n  position: absolute;\n  top: 0;\n  left: 50%;\n  z-index: 4;\n  width: calc(var(--zip-gap) * 2 + 4px);\n  height: calc(var(--zip-y) + 10px);\n  transform: translateX(-50%);\n  opacity: 0;\n  pointer-events: none;\n  background:\n    linear-gradient(180deg, rgba(255,224,166,.26), rgba(255,255,255,.09) 38%, rgba(85,168,227,.03));\n  box-shadow:\n    0 0 18px rgba(255,213,135,.18),\n    0 0 50px rgba(82,163,222,.08);\n  transition: opacity 180ms ease;\n}\n#elfoIntroV3.is-pulling .elfo-v3-open-light { opacity: 1; }\n\n.elfo-v3-vignette {\n  position: absolute;\n  inset: 0;\n  z-index: 9;\n  pointer-events: none;\n  box-shadow:\n    inset 0 0 170px rgba(0,4,10,.58),\n    inset 0 -80px 120px rgba(0,0,0,.20);\n  transition: opacity 520ms ease;\n}\n#elfoIntroV3.is-opening .elfo-v3-vignette { opacity: 0; }\n\n.elfo-v3-brand {\n  position: absolute;\n  top: 22px;\n  left: 25px;\n  z-index: 14;\n  color: rgba(236,230,207,.62);\n  font: 800 9px/1.2 system-ui, sans-serif;\n  letter-spacing: .25em;\n  text-shadow: 0 2px 8px rgba(0,0,0,.82);\n  pointer-events: none;\n}\n.elfo-v3-brand::before {\n  content: '';\n  display: inline-block;\n  width: 21px;\n  height: 1px;\n  margin-right: 8px;\n  vertical-align: middle;\n  background: rgba(224,181,91,.62);\n}\n\n.elfo-v3-character {\n  position: absolute;\n  z-index: 30;\n  width: clamp(108px, 9vw, 150px);\n  aspect-ratio: 543 / 724;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  outline: 0;\n  background: transparent;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  will-change: transform, opacity;\n}\n.elfo-v3-character:focus-visible {\n  outline: 2px solid rgba(235,193,99,.95);\n  outline-offset: 7px;\n  border-radius: 16px;\n}\n\n.elfo-v3-shadow {\n  position: absolute;\n  z-index: 0;\n  left: 13%;\n  right: 13%;\n  bottom: -1.5%;\n  height: 6.6%;\n  border-radius: 50%;\n  background: rgba(0,0,0,.50);\n  filter: blur(5px);\n  transform-origin: center;\n  will-change: transform, opacity;\n  pointer-events: none;\n}\n\n.elfo-v3-flip {\n  position: absolute;\n  inset: 0;\n  z-index: 2;\n  transform: scaleX(var(--elfo-face, 1));\n  transform-origin: 50% 90%;\n  will-change: transform;\n}\n\n.elfo-v3-visual {\n  position: absolute;\n  inset: 0;\n  transform-origin: 50% 92%;\n  will-change: transform;\n}\n\n.elfo-v3-frame-window {\n  position: absolute;\n  inset: 0;\n  overflow: hidden;\n  pointer-events: none;\n  filter: drop-shadow(0 8px 7px rgba(0,0,0,.36));\n}\n\n.elfo-v3-sheet {\n  position: absolute;\n  top: 0;\n  left: 0;\n  display: block;\n  width: 400%;\n  max-width: none !important;\n  height: 100%;\n  object-fit: fill;\n  transform: translate3d(0,0,0);\n  transform-origin: 0 0;\n  will-change: transform;\n  pointer-events: none;\n  user-select: none;\n  -webkit-user-drag: none;\n}\n\n.elfo-v3-puller {\n  position: absolute;\n  z-index: 35;\n  width: clamp(155px, 15.2vw, 235px);\n  height: auto;\n  display: none;\n  opacity: 0;\n  pointer-events: none;\n  filter: drop-shadow(0 14px 11px rgba(0,0,0,.42));\n  transform-origin: 81.5% 8.5%;\n  will-change: left, top, transform, opacity;\n}\n#elfoIntroV3.is-sequencing .elfo-v3-puller { display: block; }\n\n.elfo-v3-hint {\n  position: absolute;\n  z-index: 16;\n  left: 50%;\n  bottom: 20px;\n  transform: translateX(-50%);\n  color: rgba(238,240,241,.63);\n  font: 650 11px/1.4 system-ui, sans-serif;\n  letter-spacing: .025em;\n  text-shadow: 0 2px 9px rgba(0,0,0,.82);\n  pointer-events: none;\n  opacity: 0;\n  animation: elfoV9HintIn .7s 1s ease forwards;\n  transition: opacity 220ms ease;\n}\n#elfoIntroV3.is-sequencing .elfo-v3-hint { opacity: 0 !important; }\n\n@keyframes elfoV9HintIn {\n  from { opacity: 0; transform: translate(-50%, 7px); }\n  to   { opacity: .66; transform: translate(-50%, 0); }\n}\n\n@media (max-width: 700px) {\n  .elfo-v3-character { width: clamp(94px, 24vw, 124px); }\n  .elfo-v3-puller { width: clamp(145px, 39vw, 198px); }\n  .elfo-v3-brand { top: 15px; left: 15px; font-size: 8px; }\n  .elfo-v3-hint { bottom: 13px; font-size: 10px; }\n}\n"
JS_CONTENT = "(() => {\n  'use strict';\n\n  const root = document.getElementById('elfoIntroV3');\n  if (!root) return;\n\n  const leftPanel = root.querySelector('.elfo-v3-left');\n  const rightPanel = root.querySelector('.elfo-v3-right');\n  const actor = root.querySelector('#elfoV3Character');\n  const flip = actor.querySelector('.elfo-v3-flip');\n  const visual = actor.querySelector('.elfo-v3-visual');\n  const sheet = actor.querySelector('.elfo-v3-sheet');\n  const shadow = actor.querySelector('.elfo-v3-shadow');\n  const puller = root.querySelector('#elfoV3Puller');\n\n  document.documentElement.classList.add('elfo-intro-active');\n\n  const FRAMES = [0, 1, 2, 3];\n  const FRAME_DISTANCE = 17.5;\n  const BASE_ART_FACES_LEFT = true;\n\n  const clamp = (n, a, b) => Math.min(b, Math.max(a, n));\n  const lerp = (a, b, t) => a + (b - a) * t;\n  const smooth = t => t * t * (3 - 2 * t);\n  const easeOutCubic = t => 1 - Math.pow(1 - t, 3);\n  const easeOutQuint = t => 1 - Math.pow(1 - t, 5);\n  const moveToward = (v, t, d) => v < t ? Math.min(v + d, t) : v > t ? Math.max(v - d, t) : t;\n\n  let state = 'roam';\n  let x = Math.max(20, innerWidth * .10);\n  let y = 0;\n  let vx = 0;\n  let targetX = Math.max(20, innerWidth * .76);\n  let autoDir = 1;\n  let pointerX = targetX;\n  let pointerSeen = false;\n  let lastPointerAt = 0;\n  let lastTime = performance.now();\n  let strideDistance = 0;\n  let walkFrame = 0;\n  let currentFrame = -1;\n  let idleClock = 0;\n  let sequenceToken = 0;\n  let hoverHopBusy = false;\n\n  function actorSize() {\n    const r = actor.getBoundingClientRect();\n    return { w: r.width || 125, h: r.height || 167 };\n  }\n\n  function groundY() {\n    const { h } = actorSize();\n    return innerHeight - h - Math.max(14, innerHeight * .025);\n  }\n\n  function setFrame(frame) {\n    frame = clamp(frame | 0, 0, 3);\n    if (frame === currentFrame) return;\n    currentFrame = frame;\n    sheet.style.transform = `translate3d(${-frame * 25}%,0,0)`;\n  }\n\n  function setFacing(dir) {\n    if (Math.abs(dir) < .001) return;\n    const face = BASE_ART_FACES_LEFT ? (dir > 0 ? -1 : 1) : (dir > 0 ? 1 : -1);\n    flip.style.setProperty('--elfo-face', String(face));\n  }\n\n  function setPos(nx, ny) {\n    x = nx;\n    y = ny;\n    actor.style.transform = `translate3d(${x.toFixed(2)}px,${y.toFixed(2)}px,0)`;\n  }\n\n  function resetPose() {\n    strideDistance = 0;\n    walkFrame = 0;\n    setFrame(0);\n    visual.style.transform = '';\n    shadow.style.transform = 'scaleX(1)';\n    shadow.style.opacity = '.50';\n  }\n\n  function advanceWalk(distance, speed) {\n    strideDistance += Math.abs(distance);\n    while (strideDistance >= FRAME_DISTANCE) {\n      strideDistance -= FRAME_DISTANCE;\n      walkFrame = (walkFrame + 1) % FRAMES.length;\n      setFrame(FRAMES[walkFrame]);\n    }\n\n    const speedN = clamp(Math.abs(speed) / 225, 0, 1);\n    const phase = (walkFrame + strideDistance / FRAME_DISTANCE) / FRAMES.length * Math.PI * 2;\n    const bob = Math.abs(Math.sin(phase)) * (1.8 + speedN * 1.7);\n    const lean = clamp(speed / 225, -1, 1) * 1.15;\n\n    visual.style.transform = `translateY(${-bob.toFixed(2)}px) rotate(${lean.toFixed(2)}deg)`;\n    shadow.style.transform = `scaleX(${(1 - Math.abs(Math.sin(phase)) * .08 - speedN * .03).toFixed(3)})`;\n    shadow.style.opacity = String(.50 - Math.abs(Math.sin(phase)) * .08 - speedN * .03);\n  }\n\n  function idlePose(dt) {\n    idleClock += dt;\n    setFrame(0);\n    const breath = Math.sin(idleClock * 1.8);\n    visual.style.transform = `translateY(${(-Math.max(0, breath) * .75).toFixed(2)}px)`;\n    shadow.style.transform = `scaleX(${(1 - Math.abs(breath) * .015).toFixed(3)})`;\n    shadow.style.opacity = String(.50 - Math.abs(breath) * .012);\n  }\n\n  function updateRoam(now) {\n    const dt = Math.min(.034, Math.max(.001, (now - lastTime) / 1000));\n    lastTime = now;\n\n    const { w } = actorSize();\n    y = groundY();\n\n    const pointerActive = pointerSeen && now - lastPointerAt < 4800;\n    const leftBound = Math.max(14, innerWidth * .055);\n    const rightBound = Math.max(leftBound, innerWidth - w - Math.max(14, innerWidth * .055));\n\n    if (pointerActive) {\n      targetX = clamp(pointerX - w * .5, 10, innerWidth - w - 10);\n    } else if (Math.abs(targetX - x) < 12 || targetX < leftBound || targetX > rightBound) {\n      autoDir *= -1;\n      targetX = autoDir > 0 ? rightBound : leftBound;\n    }\n\n    const dx = targetX - x;\n    const deadZone = pointerActive ? 5.5 : 8;\n    let desiredV = 0;\n\n    if (Math.abs(dx) > deadZone) {\n      const maxSpeed = pointerActive ? 220 : 102;\n      const minSpeed = pointerActive ? 70 : 54;\n      desiredV = Math.sign(dx) * clamp(minSpeed + Math.abs(dx) * 1.38, minSpeed, maxSpeed);\n    }\n\n    const accelerating = Math.sign(desiredV) === Math.sign(vx) && Math.abs(desiredV) > Math.abs(vx);\n    vx = moveToward(vx, desiredV, (desiredV === 0 ? 830 : (accelerating ? 530 : 930)) * dt);\n\n    let delta = vx * dt;\n    if (desiredV !== 0 && Math.sign(delta) === Math.sign(dx) && Math.abs(delta) > Math.abs(dx)) {\n      delta = dx;\n      vx = 0;\n    }\n\n    x = clamp(x + delta, 8, innerWidth - w - 8);\n    const moving = Math.abs(vx) > 7 && Math.abs(delta) > .04;\n\n    if (moving) {\n      setFacing(vx);\n      advanceWalk(delta, vx);\n    } else {\n      strideDistance = 0;\n      walkFrame = 0;\n      idlePose(dt);\n    }\n\n    setPos(x, y);\n  }\n\n  function loop(now) {\n    if (state === 'roam') updateRoam(now);\n    requestAnimationFrame(loop);\n  }\n\n  function animate(ms, update, easing = t => t) {\n    return new Promise(resolve => {\n      const start = performance.now();\n      const tick = now => {\n        const raw = clamp((now - start) / ms, 0, 1);\n        update(easing(raw), raw);\n        raw < 1 ? requestAnimationFrame(tick) : resolve();\n      };\n      requestAnimationFrame(tick);\n    });\n  }\n\n  async function hoverHop() {\n    if (state !== 'roam' || hoverHopBusy) return;\n    hoverHopBusy = true;\n    const baseY = groundY();\n    const start = performance.now();\n    const duration = 430;\n\n    await new Promise(resolve => {\n      const tick = now => {\n        const p = clamp((now - start) / duration, 0, 1);\n        const arc = Math.sin(Math.PI * p);\n        setPos(x, baseY - arc * 16);\n        shadow.style.transform = `scaleX(${(1 - arc * .24).toFixed(3)})`;\n        shadow.style.opacity = String(.50 - arc * .22);\n        if (p < 1 && state === 'roam') requestAnimationFrame(tick);\n        else resolve();\n      };\n      requestAnimationFrame(tick);\n    });\n\n    hoverHopBusy = false;\n  }\n\n  async function walkTo(destX, speed = 315) {\n    const startX = x;\n    const distance = destX - startX;\n    const absDistance = Math.abs(distance);\n    if (absDistance < 2) return;\n\n    setFacing(distance);\n    const duration = clamp(absDistance / speed * 1000, 300, 1450);\n    let prev = startX;\n\n    await animate(duration, p => {\n      const e = smooth(p);\n      const nx = lerp(startX, destX, e);\n      const step = nx - prev;\n      prev = nx;\n      x = nx;\n      y = groundY();\n      advanceWalk(step, Math.sign(distance) * speed);\n      setPos(x, y);\n    });\n\n    vx = 0;\n    resetPose();\n  }\n\n  function pullerGeometry() {\n    const rect = puller.getBoundingClientRect();\n    const pw = rect.width || 200;\n    const ph = rect.height || pw;\n    const anchorX = innerWidth / 2 - pw * .815;\n    const startY = Math.max(-8, innerHeight * .004);\n    return { pw, ph, anchorX, startY };\n  }\n\n  async function leapAndGrab(token) {\n    const { w } = actorSize();\n    const sx = x;\n    const sy = y;\n    const ex = innerWidth / 2 - w / 2;\n    const ey = Math.max(10, innerHeight * .018);\n\n    root.classList.add('is-sequencing');\n    puller.style.opacity = '0';\n    const g = pullerGeometry();\n    puller.style.left = `${g.anchorX}px`;\n    puller.style.top = `${g.startY}px`;\n    puller.style.transform = 'rotate(0deg)';\n\n    await animate(135, p => {\n      if (token !== sequenceToken) return;\n      const e = easeOutCubic(p);\n      visual.style.transform = `translateY(${(4.5 * e).toFixed(2)}px) scale(${(1 + .018 * e).toFixed(3)},${(1 - .035 * e).toFixed(3)})`;\n      shadow.style.transform = `scaleX(${(1 + .055 * e).toFixed(3)})`;\n    });\n\n    await animate(900, (p, raw) => {\n      if (token !== sequenceToken) return;\n      const e = easeOutQuint(p);\n      x = lerp(sx, ex, e);\n      const linearY = lerp(sy, ey, e);\n      const arc = Math.sin(Math.PI * raw) * Math.min(150, innerHeight * .175);\n      y = linearY - arc;\n      setPos(x, y);\n\n      const lift = Math.sin(Math.PI * raw);\n      visual.style.transform = `translateY(${(-lift * 2.4).toFixed(2)}px) rotate(${(lift * 2.2).toFixed(2)}deg)`;\n      shadow.style.transform = `scaleX(${(1 - lift * .48).toFixed(3)})`;\n      shadow.style.opacity = String(.50 - lift * .34);\n\n      const morph = clamp((raw - .70) / .22, 0, 1);\n      actor.style.opacity = String(1 - morph);\n      puller.style.opacity = String(morph);\n    });\n\n    actor.style.opacity = '0';\n    puller.style.opacity = '1';\n  }\n\n  function updatePanels(sliderY, gapPx) {\n    const yy = Math.round(sliderY);\n    const gap = Math.round(gapPx);\n    root.style.setProperty('--zip-y', `${yy}px`);\n    root.style.setProperty('--zip-gap', `${gap}px`);\n\n    leftPanel.style.clipPath = `polygon(0 0, calc(50% - ${gap}px) 0, 50% ${yy}px, 50% 100%, 0 100%)`;\n    rightPanel.style.clipPath = `polygon(calc(50% + ${gap}px) 0, 100% 0, 100% 100%, 50% 100%, 50% ${yy}px)`;\n  }\n\n  async function pullZipper(token) {\n    root.classList.add('is-pulling');\n    const { pw, ph, anchorX, startY } = pullerGeometry();\n    const endY = Math.max(170, innerHeight - ph * .72 - 22);\n    const maxGap = Math.min(250, innerWidth * .105);\n\n    updatePanels(0, 0);\n\n    await animate(1960, (p, raw) => {\n      if (token !== sequenceToken) return;\n\n      // Slight initial resistance, then a steady pull, then a soft finish.\n      const e = smooth(p);\n      const py = lerp(startY, endY, e);\n      const sliderY = clamp(py + pw * .115, 0, innerHeight);\n      const gap = maxGap * Math.pow(e, .82);\n      const settle = Math.sin(raw * Math.PI) * .65;\n\n      puller.style.left = `${anchorX}px`;\n      puller.style.top = `${py}px`;\n      puller.style.transform = `rotate(${(-1.0 + e * 1.4 + settle * .25).toFixed(2)}deg)`;\n      updatePanels(sliderY, gap);\n    });\n  }\n\n  async function beginSequence() {\n    if (state !== 'roam') return;\n    state = 'sequence';\n    pointerSeen = false;\n    vx = 0;\n    const token = ++sequenceToken;\n    const { w } = actorSize();\n\n    await walkTo(innerWidth / 2 - w / 2, 325);\n    if (token !== sequenceToken) return;\n\n    await new Promise(r => setTimeout(r, 90));\n    await leapAndGrab(token);\n    if (token !== sequenceToken) return;\n\n    await new Promise(r => setTimeout(r, 65));\n    await pullZipper(token);\n    if (token !== sequenceToken) return;\n\n    root.classList.add('is-opening');\n    puller.style.transition = 'opacity 300ms ease, transform 520ms cubic-bezier(.2,.8,.2,1)';\n    puller.style.opacity = '0';\n    puller.style.transform += ' translateY(24px)';\n\n    await new Promise(r => setTimeout(r, 1100));\n    document.documentElement.classList.remove('elfo-intro-active');\n    root.hidden = true;\n    state = 'done';\n  }\n\n  document.addEventListener('pointermove', e => {\n    if (state !== 'roam') return;\n    pointerSeen = true;\n    pointerX = e.clientX;\n    lastPointerAt = performance.now();\n  }, { passive: true });\n\n  actor.addEventListener('pointerenter', hoverHop);\n  actor.addEventListener('click', beginSequence);\n  actor.addEventListener('keydown', e => {\n    if (e.key === 'Enter' || e.key === ' ') {\n      e.preventDefault();\n      beginSequence();\n    }\n  });\n\n  addEventListener('resize', () => {\n    if (state !== 'roam') return;\n    const { w } = actorSize();\n    x = clamp(x, 8, innerWidth - w - 8);\n    y = groundY();\n    setPos(x, y);\n  });\n\n  requestAnimationFrame(() => {\n    y = groundY();\n    setFrame(0);\n    setFacing(1);\n    setPos(x, y);\n    requestAnimationFrame(loop);\n  });\n})();\n"

def fail(msg: str, code: int = 1):
    print(f"ERROR: {msg}")
    raise SystemExit(code)

def main():
    root = Path.cwd()
    frontend = root / "frontend"
    if not frontend.is_dir():
        fail("این فایل باید در ریشه پروژه اجرا شود؛ پوشه frontend پیدا نشد.")

    index_path = frontend / "index.html"
    css_path = frontend / "elfo-intro-v3.css"
    js_path = frontend / "elfo-intro-v3.js"
    required_assets = [
        frontend / "elfo-walk-v3.png",
        frontend / "elfo-puller-v3.png",
        frontend / "denim-zip-v3.png",
    ]
    for p in [index_path, css_path, js_path, *required_assets]:
        if not p.exists():
            fail(f"فایل مورد نیاز پیدا نشد: {p}")

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / f"_backup_elfo_intro_v9_{stamp}"
    backup_dir.mkdir(parents=True, exist_ok=True)
    for p in (index_path, css_path, js_path):
        shutil.copy2(p, backup_dir / p.name)

    css_path.write_text(CSS_CONTENT, encoding="utf-8", newline="\n")
    js_path.write_text(JS_CONTENT, encoding="utf-8", newline="\n")

    index_text = index_path.read_text(encoding="utf-8")
    new_index = re.sub(r'(/static/elfo-intro-v3\.css\?v=)([^"\']+)', r'\g<1>9', index_text)
    new_index = re.sub(r'(/static/elfo-intro-v3\.js\?v=)([^"\']+)', r'\g<1>9', new_index)
    if new_index == index_text:
        print("WARNING: لینک نسخه intro در index.html پیدا نشد؛ CSS و JS با این حال جایگزین شدند.")
    else:
        index_path.write_text(new_index, encoding="utf-8", newline="\n")

    try:
        check = subprocess.run(["node", "--check", str(js_path)], capture_output=True, text=True)
        if check.returncode != 0:
            fail("JavaScript جدید خطای syntax دارد:\n" + check.stderr)
    except FileNotFoundError:
        print("NOTE: node نصب نیست؛ بررسی syntax جاوااسکریپت انجام نشد.")

    print("DONE: Intro V9 نصب شد.")
    print("استفاده از assetهای اصلی: Elfo walk + Elfo puller + denim zipper")
    print(f"Backup: {backup_dir}")
    print("هیچ فایل backend یا منطق گزارش‌ها تغییر نکرد.")

if __name__ == "__main__":
    main()
